def _parse_money(value: str) -> Decimal:
    """The dollar amount on a line.

    The amount is written first ("Linehaul: $2,150.00"); any notes after it
    ("$100.00 (1 extra stop)", "$75.00/hr after 2 hrs free") contain numbers
    that are not money. Prefer the first dollar-prefixed amount, falling back
    to the first number when the line has no dollar sign.
    """
    money = _MONEY.search(value)
    if money:
        return Decimal(money.group(1).replace(",", ""))
    numbers = _NUMBER.findall(value)
    if not numbers:
        raise RateConError(f"no amount in {value!r}")
    return Decimal(numbers[0].replace(",", ""))

def _bridge_spans(axle_count: int, tandems: set[int]) -> list[tuple[int, int]]:
    """Every group of two or more consecutive axles the bridge formula applies to.

    The formula applies to every such group, not just the outer bridge; interior
    groups are not held down by the single and tandem limits alone. A group that
    is exactly one tandem is covered by the tandem limit instead.
    """
    spans = []
    for first in range(axle_count):
        for last in range(first + 1, axle_count):
            if last - first == 1 and first in tandems:
                continue
            spans.append((first, last))
    return spans

